# Remove each matched song from all original playlists that contain it
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    # Skip the archived playlist if it somehow appears (it shouldn't, but safe)
    if playlist_id == 654:
        continue
    for song_id in matched_song_ids:
        if song_id in playlist['song_ids']:
            result = apis.spotify.remove_song_from_playlist(
                playlist_id=playlist_id,
                song_id=song_id,
                access_token=spotify_token
            )
            print(f"Removed song {song_id} from playlist {playlist_id}: {result}")

