# Search for each song to get its song_id
song_ids_to_archive = []
for song in songs_to_archive:
    # Search by title
    results = apis.spotify.search_songs(query=song["title"], access_token=spotify_token, page_limit=20)
    # Find matching artist
    found = None
    for r in results:
        # Check if any artist matches
        for artist in r.get("artists", []):
            if artist["name"].lower() == song["artist"].lower():
                found = r
                break
        if found:
            break
    if found:
        song_ids_to_archive.append(found["song_id"])
        print(f"Found: {song['title']} by {song['artist']} -> song_id {found['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal found: {len(song_ids_to_archive)}")

