# Parse the note content to extract songs and identify those with TODO release month.
import re

lines = note['content'].split('\n')
songs = []
for line in lines:
    line = line.strip()
    if line.startswith('- '):
        # Remove leading '- '
        line = line[2:]
        # Split on ' BY ' to get song and artist part
        if ' BY ' in line:
            song_part, artist_part = line.split(' BY ', 1)
            # artist_part may contain ' RELEASED_AT ...'
            if ' RELEASED_AT ' in artist_part:
                artist, released = artist_part.split(' RELEASED_AT ', 1)
                songs.append({'song': song_part, 'artist': artist, 'released': released})
            else:
                # Should not happen
                songs.append({'song': song_part, 'artist': artist_part, 'released': None})
        else:
            # No BY? skip
            pass

# Print songs with TODO
for s in songs:
    if s['released'] == 'TODO':
        print(s['song'], '|', s['artist'])
    else:
        print('DONE:', s['song'], '|', s['artist'], '|', s['released'])

