lines = content.strip().split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        # Extract song info
        line = line[2:]  # remove "- "
        # Split on " BY " to get title and artist part
        if ' BY ' in line:
            title_part, artist_part = line.split(' BY ', 1)
        else:
            title_part = line
            artist_part = ''
        # Extract release info
        if ' RELEASED_AT ' in artist_part:
            artist_part, release = artist_part.split(' RELEASED_AT ', 1)
        else:
            release = ''
        songs.append({
            'title': title_part.strip(),
            'artists': artist_part.strip(),
            'release': release.strip()
        })

# Print songs with TODO
