steps.code:
# Parse the note content to extract songs with RELEASED_AT TODO
lines = note['content'].split('\n')
songs_todo = []
for line in lines:
    if line.startswith('- '):
        # Remove leading "- "
        entry = line[2:]
        # Split on " RELEASED_AT "
        if ' RELEASED_AT ' in entry:
            song_part, released = entry.split(' RELEASED_AT ', 1)
            if released == 'TODO':
                # Split song_part on " BY " to get title and artists
                if ' BY ' in song_part:
                    title, artists_str = song_part.split(' BY ', 1)
                    artists = [a.strip() for a in artists_str.split(',')]
                    songs_todo.append({'title': title.strip(), 'artists': artists, 'line': line})
                else:
                    # No artists? treat as title only
                    songs_todo.append({'title': song_part.strip(), 'artists': [], 'line': line})
print(songs_todo)

