steps.code:
# Get release dates for all liked songs using show_song
release_dates = {}
for song in liked_songs:
    song_detail = apis.spotify.show_song(song_id=song['song_id'], access_token=spotify_token)
    if song_detail:
        release_date = song_detail.get('release_date')
        if release_date:
            # Format to MM/YYYY
            from datetime import datetime
            dt = datetime.fromisoformat(release_date)
            release_dates[song['title']] = dt.strftime('%m/%Y')
        else:
            print(f"No release_date for {song['title']}")
    else:
        print(f"Could not fetch song {song['song_id']}")

print("Release dates from Spotify:")
for title, rd in release_dates.items():
    print(f"{title}: {rd}")

